<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>'Profile','subtitle'=>'Update limited personal information for your account.']) ?><section class="panel form-panel"><form method="post" action="<?= site_url('profile') ?>" class="form-grid"><?= csrf_field() ?><label>Username<input value="<?= esc($user['username']) ?>" disabled></label><label>Role<input value="<?= esc(role_label($user['role'])) ?>" disabled></label><label>Display Name<input name="display_name" value="<?= esc(old('display_name',$user['display_name'])) ?>" required<?= form_invalid('display_name') ?>><?= form_error('display_name') ?></label><label>Email<input type="email" name="email" value="<?= esc(old('email',$user['email']??'')) ?>"<?= form_invalid('email') ?>><?= form_error('email') ?></label><label>Contact Number<input name="contact_number" value="<?= esc(old('contact_number',$user['contact_number']??'')) ?>"<?= form_invalid('contact_number') ?>><?= form_error('contact_number') ?></label><label class="wide-field">Address<textarea name="address" rows="3"<?= form_invalid('address') ?>><?= esc(old('address',$user['address']??'')) ?></textarea><?= form_error('address') ?></label><label>New Password <small>Leave blank to keep current password</small><span class="password-field"><input id="profile-password" type="password" name="password" minlength="8" autocomplete="new-password"<?= form_invalid('password') ?>><button type="button" data-password-toggle="profile-password" aria-label="Show password" aria-pressed="false" title="Show password"><?= ui_icon('eye') ?></button></span><?= form_error('password') ?></label><div class="form-actions wide-field"><button class="btn primary" type="submit">Update Profile</button></div></form></section><?= $this->endSection() ?>
